import "types"

// TimeMark — AntiHater's on-chain time mark for forensic evidence.
//
// Purpose: time-mark the SHA-256 digest of a case-file forensic bundle on TON so
// that the bundle's existence and content are provable as-of a specific block
// time, by anyone, without trusting AntiHater. The TON transaction's block time
// is the time mark.
//
// Design (locked):
//   - One `mark` operation, sent as a standard TON TEXT COMMENT (opcode
//     0x00000000 + the digest as UTF-8 text) so every explorer/wallet shows the
//     digest as a human-readable "Comment". The digest is sha256(manifest.json).
//   - NO per-mark state writes. The only stored value is the owner address,
//     fixed at deploy. Each mark lives in its transaction's inbound message
//     body, so the transaction history is the immutable audit log.
//   - Owner-restricted: only the AntiHater time-marking wallet can mark, so every
//     successful mark transaction is — by contract rule, on-chain — AntiHater's.
//
// Verification (third-party, NON-TECHNICAL — no AntiHater software, no tools):
//   1. Read the digest the AntiHater platform shows for the bundle.
//   2. Open the time-mark transaction on any public TON explorer (tonscan / tonviewer).
//   3. Read its "Comment" — it is the digest in plain text — and confirm it matches.
//   4. Confirm the block time predates the dispute and the sender is AntiHater's
//      published wallet. (To re-derive the digest yourself: `sha256sum manifest.json`.)
contract TimeMark {
    author: "AntiHater"
    version: "1.0.0"
    description: "Time-marks SHA-256 forensic-bundle digests on TON; tx history is the audit log"
    storage: Storage
    incomingMessages: AllowedMessage
}

type AllowedMessage =
    | Mark
    | ChangeOwner

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessage.fromSlice(in.body);

    match (msg) {
        Mark => {
            // Read-only owner check. No save() — marking never mutates storage.
            // The digest text is now permanently recorded in this transaction's
            // body (the comment); the transaction's block time is the time mark.
            val storage = lazy Storage.load();
            assert (in.senderAddress == storage.owner) throw Errors.NotOwner;
        }
        ChangeOwner => {
            var storage = lazy Storage.load();
            assert (in.senderAddress == storage.owner) throw Errors.NotOwner;
            storage.owner = msg.newOwner;
            storage.save();
        }
        else => {
            // Allow plain (empty-body) transfers — e.g. topping up the contract
            // for rent — but reject any unrecognised opcode.
            assert (in.body.isEmpty()) throw Errors.InvalidMessage;
        }
    }
}

fun onBouncedMessage(_in: InMessageBounced) {}

get fun owner(): address {
    val storage = lazy Storage.load();
    return storage.owner;
}

// Storage, messages and error codes for the TimeMark contract.
//
// The contract holds a single owner address (the AntiHater time-marking wallet),
// written once at deploy time and never grown. Marking writes NO state: the
// digest travels in the inbound message body, so the contract's transaction
// history IS the append-only log of every time-marked evidence bundle.

enum Errors {
    NotOwner = 100         // sender is not the time-marking wallet
    InvalidMessage = 0xFFFF // unrecognised opcode on a non-empty body
}

struct Storage {
    owner: address
}

fun Storage.load(): Storage {
    return Storage.fromCell(contract.getData());
}

fun Storage.save(self) {
    contract.setData(self.toCell());
}

// Mark — time-mark one forensic bundle digest, sent as a standard TON TEXT
// COMMENT: opcode 0x00000000 followed by UTF-8 text. EVERY TON explorer and
// wallet renders an opcode-0 body as a human-readable "Comment", so a
// non-technical verifier just reads the digest straight off the explorer page
// and matches it to the AntiHater platform — no API, no decoding, no tools.
// The text is "AntiHater forensic time-mark sha256:<64-hex-digest>", where the
// digest is sha256(manifest.json) for the case-file evidence bundle. The contract
// does not parse the text; the value — together with the transaction's block time
// — is recorded permanently in this transaction's inbound message body.
struct (0x00000000) Mark {
    comment: RemainingBitsAndRefs
}

// Rotate the time-marking wallet (e.g. proactive key rotation). Owner-only.
struct (0x2ce05111) ChangeOwner {
    newOwner: address
}
